const MEDIA_OBJECT_PATH =
  /^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})\/([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})\.(mp4|webm|mov|m4v|jpg|jpeg|png|webp)$/i;

/** Accept only the owner/UUID object keys generated by ArinX uploads. */
export function isSafeMediaObjectPath(path: string, ownerId?: string): boolean {
  const match = MEDIA_OBJECT_PATH.exec(path);
  return !!match && (!ownerId || match[1]?.toLowerCase() === ownerId.toLowerCase());
}